messages.content:
Tool response:
Tool: find_listings
Description: Find Listings
Parameters:
    {
      "type": "object",
      "properties": {
        "city": {
          "type": "string",
          "description": "City name",
          "title": "City"
        },
        "state": {
          "type": "string",
          "description": "State abbreviation",
          "title": "State"
        },
        "check_in": {
          "type": "string",
          "description": "Check-in date (YYYY-MM-DD)",
          "title": "Check In"
        },
        "check_out": {
          "type": "string",
          "description": "Check-out date (YYYY-MM-DD)",
          "title": "Check Out"
        },
        "min_rating": {
          "type": "number",
          "description": "Minimum average rating",
          "default": 4.8,
          "title": "Min Rating"
        },
        "min_reviews": {
          "type": "integer",
          "description": "Minimum number of reviews",
          "default": 20,
          "title": "Min Reviews"
        },
        "is_pet_friendly": {
          "anyOf": [
            {
              "type": "boolean"
            },
            {
              "type": "null"
            }
          ],
          "description": "Filter for pet-friendly listings",
          "title": "Is Pet Friendly"
        },
        "has_hot_tub": {
          "anyOf": [
            {
              "type": "boolean"
            },
            {
              "type": "null"
            }
          ],
          "description": "Filter for listings with hot tub",
          "title": "Has Hot Tub"
        }
      },
      "required": [
        "city",
        "state",
        "check_in",
        "check_out"
      ]
    }
